import{_ as t,o as i,c as a,a0 as o}from"./chunks/framework.CShDTZbC.js";const m=JSON.parse('{"title":"Micro1 Agentic Workflows Hackathon - Competition Rules","description":"","frontmatter":{},"headers":[],"relativePath":"internals/hackathon-archive/competition-rules.md","filePath":"internals/hackathon-archive/competition-rules.md"}'),n={name:"internals/hackathon-archive/competition-rules.md"};function r(l,e,s,u,h,c){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="micro1-agentic-workflows-hackathon-competition-rules" tabindex="-1">Micro1 Agentic Workflows Hackathon - Competition Rules <a class="header-anchor" href="#micro1-agentic-workflows-hackathon-competition-rules" aria-label="Permalink to &quot;Micro1 Agentic Workflows Hackathon - Competition Rules&quot;">​</a></h1><p>This document extracts and organizes the rules, requirements, and principles strictly from the official competition PDF.</p><h2 id="a-official-competition-requirements" tabindex="-1">A. OFFICIAL COMPETITION REQUIREMENTS <a class="header-anchor" href="#a-official-competition-requirements" aria-label="Permalink to &quot;A. OFFICIAL COMPETITION REQUIREMENTS&quot;">​</a></h2><h3 id="_1-challenge-objective" tabindex="-1">1. Challenge Objective <a class="header-anchor" href="#_1-challenge-objective" aria-label="Permalink to &quot;1. Challenge Objective&quot;">​</a></h3><p>Choose a problem worth solving and use agents to create something people would genuinely find useful. Keep it practical, share what you learn and have fun.</p><h3 id="_2-four-central-questions" tabindex="-1">2. Four Central Questions <a class="header-anchor" href="#_2-four-central-questions" aria-label="Permalink to &quot;2. Four Central Questions&quot;">​</a></h3><ol><li>Who has this problem?</li><li>What bottleneck makes it worth solving?</li><li>Does the agent solve it well?</li><li>Can another person reproduce the result?</li></ol><h3 id="_3-problem-requirements" tabindex="-1">3. Problem Requirements <a class="header-anchor" href="#_3-problem-requirements" aria-label="Permalink to &quot;3. Problem Requirements&quot;">​</a></h3><p>Pick a specific and meaningful problem you understand. Explain who has the problem, the bottleneck they face, and why solving it would be valuable in practice. The goal is to create something a real person would want to use.</p><h3 id="_4-agent-requirements-design-principles" tabindex="-1">4. Agent Requirements / Design Principles <a class="header-anchor" href="#_4-agent-requirements-design-principles" aria-label="Permalink to &quot;4. Agent Requirements / Design Principles&quot;">​</a></h3><ul><li>Use whichever agent capabilities help solve the problem well (e.g., better context, better tools, memory, verification, specialized skills, or orchestration).</li><li>Choose the approach that fits your problem.</li><li><strong>Rule:</strong> Purposeful choices matter more than the number of components.</li><li><strong>Rule:</strong> Each design choice must improve the solution and help the agent reach the goal reliably.</li></ul><h3 id="_5-baseline-requirements" tabindex="-1">5. Baseline Requirements <a class="header-anchor" href="#_5-baseline-requirements" aria-label="Permalink to &quot;5. Baseline Requirements&quot;">​</a></h3><ul><li>Create a simple baseline that represents a reasonable basic way to handle the task before using your solution (e.g., one direct prompt, one general purpose agent, a simple script/template, or the manual process people use today).</li><li><strong>Rule:</strong> Keep the comparison fair by giving the baseline and final solution the <strong>same task and evaluation cases</strong>.</li><li>Explain any meaningful difference in the resources available to each one.</li><li>Use the final baseline comparison to show the size of the overall improvement.</li></ul><h3 id="_6-evaluation-requirements" tabindex="-1">6. Evaluation Requirements <a class="header-anchor" href="#_6-evaluation-requirements" aria-label="Permalink to &quot;6. Evaluation Requirements&quot;">​</a></h3><ul><li>Choose <strong>one primary metric</strong> that reflects what success means to the user (e.g., tests pass, time saved, cost reduced, calibration).</li><li>Define what a good final result looks like before running the evaluation.</li><li>Target <strong>10 or more cases</strong> when the task allows it.</li><li>Include <strong>one challenging case</strong> and explain what it revealed.</li><li>Run this evaluation yourself, or design a clear scoring rubric and propose it for judges.</li></ul><h3 id="_7-improvement-changelog" tabindex="-1">7. Improvement Changelog <a class="header-anchor" href="#_7-improvement-changelog" aria-label="Permalink to &quot;7. Improvement Changelog&quot;">​</a></h3><ul><li>Create a short changelog that tells the story of how your solution evolved from the baseline to the final result.</li><li>Add one entry for every important experiment, explaining what you tried and why.</li><li>Show the result using the same evaluation method whenever possible, and share what you decided to do next.</li><li>Include experiments you later removed and explain what they taught you about the problem.</li></ul><h3 id="_8-judging-rubric-and-point-weights-100-points-total" tabindex="-1">8. Judging Rubric and Point Weights (100 Points Total) <a class="header-anchor" href="#_8-judging-rubric-and-point-weights-100-points-total" aria-label="Permalink to &quot;8. Judging Rubric and Point Weights (100 Points Total)&quot;">​</a></h3><ul><li><strong>Problem &amp; User Value (15 points):</strong> A strong project solves a meaningful problem for a clearly defined user.</li><li><strong>Agent Solution &amp; Engineering (30 points):</strong> A strong solution uses agents purposefully and is technically sound.</li><li><strong>End to End Quality (20 points):</strong> Completes a realistic and self-contained execution and produces a final result the user can use (should read like a finished product, not an obvious AI draft).</li><li><strong>Measured Improvement (15 points):</strong> Demonstrates gains over a fair baseline and uses the changelog to connect iterations with evidence.</li><li><strong>Reproducibility (15 points):</strong> Gives another person a clear path to run the solution and baseline and reach the main result from a clean environment.</li><li><strong>Hot Take / Insights (5 points):</strong> Turns an observed failure mode into a practical lesson for building more reliable agents.</li></ul><h3 id="_9-ground-rules" tabindex="-1">9. Ground Rules <a class="header-anchor" href="#_9-ground-rules" aria-label="Permalink to &quot;9. Ground Rules&quot;">​</a></h3><ol><li>You are welcome to build with tools and components you already know.</li><li>Make it clear what existed before the competition and what you added.</li><li>Use every tool and component according to its license and service terms.</li><li>Keep consequential actions controlled through a sandbox or simulation. Add human approval before the action happens.</li><li>Make a qualified human reviewer part of any solution that could significantly affect someone.</li><li>Choose a legal and ethical use case that treats people and their data responsibly.</li><li>Use information you are allowed to share (public, synthetic, or approved anonymous data).</li><li>Keep credentials and private information outside the submission.</li><li>Connect every claim about your results to the evidence you submit.</li><li>Give judges enough access to run the project and reproduce the main result.</li></ol><h3 id="_10-final-deliverables" tabindex="-1">10. Final Deliverables <a class="header-anchor" href="#_10-final-deliverables" aria-label="Permalink to &quot;10. Final Deliverables&quot;">​</a></h3><p>Submit the following four items:</p><ol><li>Complete solution code and improvement changelog</li><li>Reproduction guide</li><li>Solution video</li><li>Agent trajectories</li></ol><h3 id="_11-video-requirements" tabindex="-1">11. Video Requirements <a class="header-anchor" href="#_11-video-requirements" aria-label="Permalink to &quot;11. Video Requirements&quot;">​</a></h3><ul><li>Maximum 5 minutes.</li><li>Begin with the problem and simple baseline.</li><li>Walk through one realistic execution from start to finish.</li><li>Show the final comparison.</li><li>Briefly explain the changelog, highlighting the change that contributed most, as well as one experiment you removed.</li></ul><h3 id="_12-trajectory-requirements" tabindex="-1">12. Trajectory Requirements <a class="header-anchor" href="#_12-trajectory-requirements" aria-label="Permalink to &quot;12. Trajectory Requirements&quot;">​</a></h3><ul><li>Include representative trajectories for <strong>every agent you used</strong>.</li><li>Make each trajectory easy to follow from instructions to final result.</li><li>Show what the agent did, how tools responded, feedback that shaped next steps, retries, and human checkpoints.</li></ul><h3 id="_13-reproducibility-requirements" tabindex="-1">13. Reproducibility Requirements <a class="header-anchor" href="#_13-reproducibility-requirements" aria-label="Permalink to &quot;13. Reproducibility Requirements&quot;">​</a></h3><ul><li>Write for someone starting from a clean environment.</li><li>Walk through setup and provide exact commands for the solution, baseline, and evaluation.</li><li>Explain data required and expected output.</li><li>Share relevant versions, approximate runtime, and cost.</li></ul><h3 id="_14-data-privacy-security-requirements" tabindex="-1">14. Data / Privacy / Security Requirements <a class="header-anchor" href="#_14-data-privacy-security-requirements" aria-label="Permalink to &quot;14. Data / Privacy / Security Requirements&quot;">​</a></h3><ul><li>Treat people and their data responsibly.</li><li>Use information you are allowed to share (public, synthetic, approved anonymous).</li><li>Keep credentials and private information outside the submission.</li><li>Keep consequential actions controlled in a sandbox or via human approval.</li></ul><h3 id="_15-potential-point-loss-risks" tabindex="-1">15. Potential Point-Loss Risks <a class="header-anchor" href="#_15-potential-point-loss-risks" aria-label="Permalink to &quot;15. Potential Point-Loss Risks&quot;">​</a></h3><ul><li>Lack of purposeful choices (e.g., adding agents just to add them).</li><li>Unfair baseline comparison (different tasks/cases or unexplained resource differences).</li><li>Evaluation that lacks 10+ cases or a challenging case (when practical).</li><li>Outputs that look like obvious AI-generated drafts.</li><li>Not documenting experiments that were removed.</li><li>Inability for judges to run the project and reproduce the main result from a clean environment.</li><li>Failing to distinguish what was added vs. what already existed.</li></ul><hr><h2 id="b-strategic-recommendations" tabindex="-1">B. STRATEGIC RECOMMENDATIONS <a class="header-anchor" href="#b-strategic-recommendations" aria-label="Permalink to &quot;B. STRATEGIC RECOMMENDATIONS&quot;">​</a></h2><ul><li><strong>Metric Selection:</strong> Pick a metric that genuinely matters to the user (e.g., tests passing for developers, time saved for operations). Do not pick generic metrics.</li><li><strong>Failures as Insights:</strong> Treat failure modes not as defects but as valuable engineering insights. Highlighting a removed experiment builds credibility.</li><li><strong>Self-Contained Execution:</strong> A self-contained workflow is better than a fragmented process.</li><li><strong>High-Quality Output:</strong> The agent’s final output should resemble something a person could sign their name to. Do not just spit out a generic LLM response.</li></ul><hr><h2 id="c-engineering-assumptions" tabindex="-1">C. ENGINEERING ASSUMPTIONS <a class="header-anchor" href="#c-engineering-assumptions" aria-label="Permalink to &quot;C. ENGINEERING ASSUMPTIONS&quot;">​</a></h2><ul><li><strong>Tooling:</strong> We assume that we can use any framework or SDK as long as it is properly licensed and we can document the setup commands.</li><li><strong>Evaluation:</strong> Since we must run the evaluation ourselves (or propose a rubric), we must engineer an automated testing harness or rigorous manual test suite for the 10+ cases.</li><li><strong>Logging:</strong> We need a way to capture &quot;representative trajectories&quot; for every agent. The system we build must support exporting these logs clearly.</li></ul>',40)])])}const p=t(n,[["render",r]]);export{m as __pageData,p as default};
